"""Step 2 surface backend, receiving analytic records generated inside GN.

The established Step 1 quad and height construction is retained.  Arm origins
allow paths whose reference lines do not all pass through the junction datum.
"""
from .backend_runtime import Graph, V, bounded, named, choose, rm
from . import backend_mesh as mesh_nodes
from . import backend_relax as relax_nodes
from . import backend_height as height_nodes

NAME = 'Street Blosm / Shared surface backend v1'


def build_mesh_group(*, max_pieces=3):
    suffix=' / Five pieces' if max_pieces==5 else ''
    g=Graph('Street Blosm / Direct quad construction'+suffix)
    for key in ('Arms','Patches','Pieces','Header'):g.socket(key,'NodeSocketGeometry')
    g.socket('Factor','NodeSocketInt',default=1);g.socket('Grass','NodeSocketBool',default=False)
    g.socket('Geometry','NodeSocketGeometry','OUTPUT')
    inp=g.node('NodeGroupInput')
    geo=mesh_nodes.build_geometry(g,*(inp.outputs[k] for k in ('Arms','Patches','Pieces','Header')),
                                 V(g,inp.outputs['Factor']),V(g,inp.outputs['Grass']),max_pieces=max_pieces)
    out=g.node('NodeGroupOutput');g.bind(geo,out.inputs['Geometry'])
    return g.g


def build(*, max_pieces=3):
    """Build one backend for all runtime records, with no fixture dispatch.

    Geometry carries the Step 1 record_type 0..3 schema plus the Arm ``origin``
    vector and optional Patch ``radial_mode`` integer.  All frame stations are
    relative to origin; sector and boundary control coordinates are absolute.
    """
    if max_pieces not in (3,5):raise ValueError('Supported boundary capacities are three or five pieces')
    suffix=' / Five pieces' if max_pieces==5 else ''
    mesh=build_mesh_group(max_pieces=max_pieces);relax=relax_nodes.build_group(suffix=suffix)
    fraction=height_nodes.build_fraction(max_pieces=max_pieces);crown=height_nodes.build_crown(suffix=suffix)
    g=Graph(NAME+suffix);g.g.is_modifier=True
    g.socket('Geometry','NodeSocketGeometry')
    g.socket('Geometry','NodeSocketGeometry','OUTPUT')
    r=g.socket('Mesh Resolution','NodeSocketInt',default=1);r.min_value=1;r.max_value=4
    r.description='Four coupled quad densities; 4 is the existing maximum.'
    ex=g.socket('Height Exaggeration','NodeSocketFloat',default=10.);ex.min_value=1.;ex.max_value=10.
    ex.description='Display multiplier; 1 is physical height.'
    g.socket('Grass','NodeSocketBool',default=False)
    g.socket('Material','NodeSocketMaterial')
    base=g.socket('Reference Elevation','NodeSocketFloat',default=0.)
    base.description='Shared mouth-edge datum, added after physical profile exaggeration.'
    inp=g.node('NodeGroupInput')
    g.section('Runtime analytic records produced by the Blosm input front end')
    views={key:rm.split(g,inp.outputs['Geometry'],tag) for tag,key in enumerate(('Header','Arms','Patches','Pieces'))}
    factor=g.math('POWER',2.,bounded(g,V(g,inp.outputs['Mesh Resolution']),1.,4.)-1.)

    def call(tree,geometry=None,keys=()):
        n=g.node('GeometryNodeGroup',tree.name.removeprefix('Street Blosm / '));n.node_tree=tree
        if geometry is not None:g.bind(geometry,n.inputs['Geometry'])
        for key in keys:g.bind(views[key],n.inputs[key])
        return n

    g.section('Direct quad construction and constrained XY relaxation')
    n=call(mesh,keys=('Arms','Patches','Pieces','Header'))
    g.bind(factor,n.inputs['Factor']);g.bind(inp.outputs['Grass'],n.inputs['Grass'])
    raw=V(g,n.outputs['Geometry'])
    n=call(relax,raw,('Arms',));g.bind(20.*factor,n.inputs['Iterations'])
    relaxed=V(g,n.outputs['Geometry'])
    grass=g.store(raw,'initial_xy',g.position(),'POINT','FLOAT_VECTOR')
    grass=g.store(grass,'fixed_xy',True,'POINT','BOOLEAN')
    geo=choose(g,inp.outputs['Grass'],grass,relaxed,'GEOMETRY')
    g.section('Original surface fraction and incoming crown reconciliation')
    n=call(fraction,geo,('Arms','Patches','Pieces'));geo=V(g,n.outputs['Geometry'])
    n=call(crown,geo,('Arms','Header'));geo=V(g,n.outputs['Geometry'])
    x,y,_=g.separate(g.position())
    z=named(g,'profile_fraction')*named(g,'crown_amplitude')*V(g,inp.outputs['Height Exaggeration'])
    z=z+V(g,inp.outputs['Reference Elevation'])
    geo=g.setpos(geo,g.xyz(x,y,z))
    mat=g.node('GeometryNodeSetMaterial');g.bind(geo,mat.inputs['Geometry']);g.bind(inp.outputs['Material'],mat.inputs['Material'])
    out=g.node('NodeGroupOutput');g.bind(mat.outputs['Geometry'],out.inputs['Geometry'])
    g.g['construction']='Runtime direct quads, constrained Jacobi and analytic ruled-chart height; translated arm frames.'
    g.g['record_schema_version']=2
    g.g['max_boundary_pieces']=max_pieces
    g.g['scope']='Step 2 backend: analytic records are an internal GN interface, not the Blosm input contract.'
    return g.g
